Echo Cert > API /echo-cert

{
 "info": {
 "title": "Ozone Connect - Health Check APIs",
 "contact": {
 "name": "Ozone Financial Technology Limited"
 },
 "description": "This document provides an API description in [OpenAPI](https://spec.openapis.org/oas/v3.0.1.html) for Health Check APIs for Ozone Connect.\n\nThese APIs should be implemented by an financial institution so that Ozone\ncan ensure that the institution's Ozone Connect implementation is up and running.\n\nPlease refer to the API Hub documentation for details of test cases that are\navailable for this API using the Ozone Connect test suite.\n\n### Versioning\n\nThe `version` property implements the following pattern `{standards-major}.{standards-minor}.{ozone-connect-version}`, where:\n\n* `standards-major` is the major version of the latest UAE standard that the API description implements.\n* `standards-minor` is the minor version of the latest UAE standard that the API description implements.\n* `ozone-connect-version` is the version of the Ozone Connect API description.\n\nSo, for example, `v2.0.1` indicates the first version of the Ozone Connect API description that implements the UAE standard version 2.0.\n### v2.1.2\n* Changed the `HealthCheckCertResponse.clientCertificate.subject` description and example. The endpoint echoes \n the client certificate presented by the caller during the mTLS handshake; for Open Finance UAE callers the `OU` \n carries the caller's organisation ID from the Trust Framework directory, not a DNS name in the `CN`. Refreshed \n the `issuer` example to the Sandbox Trust Framework issuing CA for symmetry.\n",
 "version": "v2.1.2"
 },
 "servers": [
 {
 "url": "https://[Ozone_Connect_API]"
 }
 ],
 "source_path": "/echo-cert",
 "operations": {
 "get": {
 "operationId": "echoCert",
 "tags": [
 "health-check"
 ],
 "summary": "Provides information about the client cert that the server received",
 "description": "This health check endpoint assists in debugging mutual tls client issues.\nThe health check returns information about the client certificate and the issuer of the client certificate that the server received.\nWhere mtls cannot be established, the server will return a 401 response.\n",
 "responses": {
 "200": {
 "description": "OK",
 "content": {
 "application/json": {
 "schema": {
 "$ref": "#/components/schemas/HealthCheckCertResponse"
 }
 }
 }
 },
 "401": {
 "$ref": "#/components/responses/UnauthorizedResponse"
 },
 "default": {
 "$ref": "#/components/responses/DefaultErrorResponse"
 }
 }
 }
 },
 "security": [
 {}
 ]
}

Echo Cert > OpenAPI definition #/components/schemas/HealthCheckCertResponse

{
 "type": "object",
 "properties": {
 "connectionEstablished": {
 "$ref": "#/components/schemas/ConnectionEstablished"
 },
 "mtlsStatus": {
 "type": "string",
 "enum": [
 "established",
 "not-established"
 ]
 },
 "hostName": {
 "$ref": "#/components/schemas/HostName"
 },
 "clientCertificate": {
 "description": "Properties of the client certificate presented by the caller during the mTLS handshake.",
 "type": "object",
 "properties": {
 "subject": {
 "description": "The Distinguished Name of the client certificate's subject. For Open Finance UAE callers, the OU contains the caller's organisation ID from the Trust Framework directory.",
 "type": "string",
 "example": "C=UK, O=OZONE FINANCIAL TECHNOLOGY LIMITED, OU=233bcd1d-4216-4b3c-a362-9e4a9282bba7"
 },
 "issuer": {
 "description": "The Distinguished Name of the issuing Certificate Authority.",
 "type": "string",
 "example": "C=AE, O=Open Finance UAE, OU=Open Finance UAE Sandbox Trust Framework, CN=Open Finance UAE Sandbox Issuing CA - G1"
 }
 },
 "required": [
 "subject",
 "issuer"
 ]
 }
 },
 "required": [
 "connectionEstablished",
 "mtlsStatus",
 "hostName",
 "clientCertificate"
 ]
}

Echo Cert > OpenAPI definition #/components/schemas/ConnectionEstablished

{
 "description": "Indicator of whether a connection was established",
 "type": "boolean"
}

Echo Cert > OpenAPI definition #/components/schemas/HostName

{
 "description": "The hostname to which the connection was attempted. Should match the hostname of the server on which the health check implementation is running.",
 "type": "string",
 "example": "auth.open-finance-apihub.ae"
}

Echo Cert > OpenAPI definition #/components/schemas/HealthCheck4xxResponse

{
 "type": "object",
 "description": "Response when connection could not be established",
 "properties": {
 "errorMessage": {
 "description": "A description of the error being experienced.",
 "type": "string"
 }
 },
 "required": [
 "errorMessage"
 ]
}

Echo Cert > OpenAPI definition #/components/responses/DefaultErrorResponse

{
 "description": "Default error response",
 "content": {
 "application/json": {
 "schema": {
 "$ref": "#/components/schemas/HealthCheck4xxResponse"
 }
 }
 }
}
